import sys

def main():
    data = sys.stdin.read().split()
    N = int(data[0])
    A = list(map(int, data[1:1+N]))

    if N == 1:
        print("Fennec")
    elif N == 2:
        print("Snuke")
    elif N == 3:
        if any(a % 2 == 1 for a in A):
            print("Fennec")
        else:
            print("Snuke")
    else:  # N >= 4
        odd_count = sum(1 for a in A if a % 2 == 1)
        if odd_count % 2 == 1:
            print("Fennec")
        else:
            print("Snuke")

main()

